import org.formasaloido.*;
import java.util.*;
import java.io.*;

public final class TraceChecks {
 static int checks;static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 interface Bad{void run()throws Exception;}static void rejects(Bad action)throws Exception{boolean rejected=false;try{action.run();}catch(IllegalArgumentException|IllegalStateException|IOException e){rejected=true;}check(rejected,"invalid data rejected");}
 public static void main(String[] args)throws Exception{
  Sound.Settings s=new Sound.Settings();TraceDrawing d=new TraceDrawing();d.begin(10,20,100,"Primero");d.add(110,20,1100);d.end();d.begin(500,350,2000,"Segundo");d.add(500,250,2500);d.end();
  check(d.strokes().size()==2&&d.pointCount()==4,"separate pen lifts");Sound.Program p=d.playback(s,-1,-1);int lines=0;for(Sound.Span a:p.spans)if(a.kind.equals("line")){lines++;check(!(a.a.x==110&&a.b.x==500),"no invented connecting stroke");check(a.duration==1||a.duration==.5,"recorded time not distance");}check(lines==2,"two actual segments");
  d.strokes().get(1).closed=true;TraceDrawing restored=TraceDrawing.decode(d.encode());check(restored.strokes().get(1).closed,"closed region preserved");check(restored.strokes().get(0).label.equals("Primero"),"labels preserved");check(restored.strokes().get(1).samples().get(1).time==2500,"timing preserved");check(restored.geometry().shapes.get(1).closed,"region geometry");restored.undo();check(restored.pointCount()==2,"undo count");restored.clear();check(restored.pointCount()==0,"clear count");
  rejects(()->TraceDrawing.decode("not base64"));rejects(()->TraceDrawing.decode(d.encode()+"AAAA"));rejects(()->d.begin(Double.NaN,0,0,"bad"));rejects(()->d.begin(601,0,0,"bad"));rejects(()->d.playback(s,5,-1));rejects(()->d.playback(s,0,5));
  TraceDrawing bounded=new TraceDrawing();bounded.begin(1,1,0,"");rejects(()->bounded.add(2,2,-1));for(int n=1;n<128;n++){bounded.end();bounded.begin(n,2,n,"");}rejects(()->bounded.begin(2,2,200,"too many"));
  for(int demo=0;demo<3;demo++){TraceDrawing sample=TraceDrawing.demo(demo);check(sample.pointCount()>5,"demo points");check(TraceDrawing.decode(sample.encode()).pointCount()==sample.pointCount(),"portable demo");check(sample.playback(s,-1,-1).duration<=180,"bounded replay");}
  int[] pixels={0xff000000,0xffffffff,0xff000000,0xffffffff};ImageScan.Raster raster=new ImageScan.Raster(pixels,2,2);Geometry.Point dark=new Geometry.Point(raster.left+raster.scale*.3,raster.top+raster.scale*.3),light=new Geometry.Point(raster.left+raster.scale*1.3,raster.top+raster.scale*.3);check(raster.value(dark,128,255,false)<.01,"black luminance");check(raster.value(light,128,255,false)>.99,"white luminance");check(raster.value(light,128,255,true)<.01,"invert luminance");check(!raster.contains(new Geometry.Point(0,0)),"letterbox excluded");
  Geometry g=new Geometry(0,Arrays.asList(new Geometry.Shape(Curriculum.points(100,100,500,100,500,350,100,350),true,false),new Geometry.Shape(Curriculum.points(250,180,350,180,350,280,250,280),true,false,3,true)));
  for(int mode=0;mode<4;mode++)for(Geometry.Point origin:Arrays.asList(new Geometry.Point(0,0),new Geometry.Point(600,0),new Geometry.Point(600,450),new Geometry.Point(0,450),new Geometry.Point(281,191))){ImageScan scan=new ImageScan(g,null,s,mode,origin,40,128,255,false);check(scan.sections.size()>0,"scan sections");Set<String> visited=new HashSet<>();for(ImageScan.Section section:scan.sections)for(Sound.Span a:section.program.spans){check(a.a.x>=0&&a.a.x<=600&&a.a.y>=0&&a.a.y<=450,"scan bounds");check(visited.add(a.a.x+","+a.a.y),"no duplicate cell");if(mode==3){check(Geometry.inside(a.a,g.shapes.get(0)),"fill inside silhouette");check(!Geometry.inside(a.a,g.shapes.get(1)),"hole not filled");}}if(mode<3)check(visited.size()==180,"complete lattice coverage");check(scan.program(s,-1).duration<=180,"bounded scan duration");}
  Sound.Program contour=ImageScan.contour(g,s,new Geometry.Point(500,350));check(contour.spans.get(0).a.distance(new Geometry.Point(500,350))<.01,"nearest contour vertex start");check(g.shapes.get(0).points.get(0).x==100,"source not moved");Sound.Program longProgram=new Sound.Program(s).moveTimed(new Geometry.Point(0,0),new Geometry.Point(600,450),5).limited(1);check(longProgram.duration==1&&longProgram.spans.get(0).b.x==120,"clipped program interpolates endpoint");
  TraceDrawing held=new TraceDrawing();held.begin(40,50,0,"Pausa");Geometry before=held.geometry();held.add(90,50,300);check(held.geometry()!=before,"geometry invalidated after recording");held.finish(1300);check(held.strokes().get(0).samples().get(2).time==1300,"pen hold end time retained");check(held.playback(s,0,-1).spans.stream().filter(a->a.kind.equals("line")).count()==2,"stationary hold reproduced");
  Sound.Settings mono=new Sound.Settings();mono.spatial=2;double previous=-1;for(double gain:new double[]{0,.2,1}){Sound.Renderer renderer=new Sound.Renderer(null);renderer.program(new Sound.Program(mono).sample(new Geometry.Point(300,225),.3,gain));short[] pcm=new short[8820];renderer.render(pcm,4410,mono);double energy=0;for(int i=0;i<pcm.length;i+=2){check(pcm[i]==pcm[i+1],"raster mono survives summation");check(Math.abs((int)pcm[i])<28000,"raster PCM bounded");energy+=(double)pcm[i]*pcm[i];}check(energy>previous,"luminance gain ordering audible in PCM");previous=energy;}
  System.out.println("PASS "+checks+" trace/scan checks: original order, timing, pen lifts, roundtrip, bounds, malformed projects, lattice coverage, quadrants, fill holes, anchors and duration.");
 }
}
